import sys
import heapq

def find(parent, i):
    if parent[i] == i:
        return i
    else:
        return find(parent, parent[i])

def union(parent, rank, x, y):
    rootX = find(parent, x)
    rootY = find(parent, y)

    if rootX != rootY:
        if rank[rootX] < rank[rootY]:
            parent[rootX] = rootY
        elif rank[rootX] > rank[rootY]:
            parent[rootY] = rootX
        else:
            parent[rootY] = rootX
            rank[rootX] += 1

def kruskal_mst(N, edges):
    result = []
    i, e = 0, 0
    edges = sorted(edges, key=lambda item: item[2])

    parent = []
    rank = []

    for node in range(N):
        parent.append(node)
        rank.append(0)

    while e < N - 1:
        u, v, w = edges[i]
        i += 1
        x = find(parent, u)
        y = find(parent, v)

        if x != y:
            e += 1
            result.append(w)
            union(parent, rank, x, y)

    return sum(result)

