        index += 3

    edges = []

    for i in range(N):
        for j in range(i + 1, N):
            cost = min(abs(coordinates[i][0] - coordinates[j][0]),
                       abs(coordinates[i][1] - coordinates[j][1]),
                       abs(coordinates[i][2] - coordinates[j][2]))
            edges.append((i, j, cost))

    min_cost = kruskal_mst(N, edges)
    print(min_cost)

